787	/// Finishes all grouping.
788	fn finish(s: &mut State) -> SourceResult<()> {
789	    finish_grouping_while(s, |s| {
790	        // If this is a fragment realization and all we've got is inline and
791	        // neutral content, don't turn it into a paragraph.
792	        if is_fully_inline_or_neutral(s) {
793	            if let RealizationKind::Fragment { kind } = &mut s.kind {
794	                **kind = FragmentKind::Inline;
795	            }
796	            s.groupings.pop();
797	            collapse_spaces(&mut s.sink, 0);
798	            false
799	        } else {
800	            !s.groupings.is_empty()
801	        }
802	    })?;
803	
804	    // In paragraph and math realization, spaces are top-level.
805	    if matches!(s.kind, RealizationKind::Par | RealizationKind::Math) {
806	        collapse_spaces(&mut s.sink, 0);
807	    }
808	
809	    Ok(())
810	}
