896	/// Finishes a grouping with the given `rule` that starts at a given position in
897	/// the sink.
898	fn finish_grouping(
899	    s: &mut State,
900	    rule: &GroupingRule,
901	    mut start: usize,
902	) -> SourceResult<()> {
903	    // Trim trailing non-trigger elements. At the start, they are already not
904	    // included precisely because they are not triggers.
905	    let trimmed = s.sink[start..]
906	        .trim_end_matches(|(c, _)| (rule.effect)(c) != GroupingEffect::Trigger);
907	    let mut end = start + trimmed.len();
908	
909	    // Tags that are opened within or at the start boundary of the grouping
910	    // should have their closing tag included if it is at the end boundary.
911	    // Similarly, tags that are closed within or at the end boundary should have
912	    // their opening tag included if it is at the start boundary. Finally, tags
913	    // that are sandwiched between an opening tag with a matching closing tag
914	    // should also be included.
915	    if rule.tags {
916	        // The trailing part of the sink can contain a mix of inner elements and
917	        // tags. If there is a closing tag with a matching start tag, but there
918	        // is an inner element in between, that's in principle a situation with
919	        // overlapping tags. However, if the inner element would immediately be
920	        // destructed anyways, there isn't really a problem. So we try to
921	        // anticipate that and destruct it eagerly.
922	        if std::ptr::eq(rule, &PAR) {
923	            for _ in s.sink.extract_if(end.., |(c, _)| c.is::<SpaceElem>()) {}
924	        }
925	
926	        // Find tags before, within, and after the grouping range.
927	        let bump = &s.arenas.bump;
928	        let before = tag_set(bump, s.sink[..start].iter().rev().map_while(to_tag));
929	        let within = tag_set(bump, s.sink[start..end].iter().filter_map(to_tag));
930	        let after = tag_set(bump, s.sink[end..].iter().map_while(to_tag));
931	
932	        // Include all tags at the start that are closed within or after.
933	        for (k, (c, _)) in s.sink[..start].iter().enumerate().rev() {
934	            let Some(elem) = c.to_packed::<TagElem>() else { break };
935	            let key = elem.tag.location().into();
936	            if within.contains(&key) || after.contains(&key) {
937	                start = k;
938	            }
939	        }
940	
941	        // Include all tags at the end that are opened within or before.
942	        for (k, (c, _)) in s.sink.iter().enumerate().skip(end) {
943	            let Some(elem) = c.to_packed::<TagElem>() else { break };
944	            let key = elem.tag.location().into();
945	            if within.contains(&key) || before.contains(&key) {
946	                end = k + 1;
947	            }
948	        }
949	    }
950	
951	    let tail = s.store_slice(&s.sink[end..]);
952	    s.sink.truncate(end);
953	
954	    // If the grouping is not interested in tags, remove and collect them.
955	    let mut tags = BumpVec::<Pair>::new_in(&s.arenas.bump);
956	    if !rule.tags {
957	        let mut k = start;
958	        for i in start..end {
959	            if s.sink[i].0.is::<TagElem>() {
960	                tags.push(s.sink[i]);
961	                continue;
962	            }
963	
964	            if k < i {
965	                s.sink[k] = s.sink[i];
966	            }
967	            k += 1;
968	        }
969	        s.sink.truncate(k);
970	    }
971	
972	    // Execute the grouping's finisher rule.
973	    (rule.finish)(Grouped { s, start })?;
974	
975	    // Visit the tags and staged elements again.
976	    for &(content, styles) in tags.iter().chain(&tail) {
977	        visit(s, content, styles)?;
978	    }
979	
980	    Ok(())
981	}
