983	/// Extracts the locations of all tags in the given `list` into a bump-allocated
984	/// set.
985	fn tag_set<'a>(
986	    bump: &'a Bump,
987	    iter: impl IntoIterator<Item = &'a Packed<TagElem>>,
988	) -> ListSet<BumpVec<'a, LocationKey>> {
989	    ListSet::new(
990	        iter.into_iter()
991	            .map(|elem| LocationKey::new(elem.tag.location()))
992	            .collect_in::<BumpVec<_>>(bump),
993	    )
994	}
